window.DICTIONARY_ENTRY_SHARDS["0077-0068"]={"0077-0068:a54f3226786e57":{"word":"WHO","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"WHO","de-DE":"WHO"},"forms":[],"senses":[{"definition":"Weltgesundheitsorganisation"},{"definition":"Welthandelsorganisation"}],"synonyms":["Weltgesundheitsorganisation","World Health Organization"],"origins":["[1] Englische Abkürzung für \"World Health Organization\"","[2] Deutsche Abkürzung für \"Welthandelsorganisation\""],"examples":[{"text":"Die Vorhersage der WHO wurde letztes Jahr übertroffen.","reference":""}],"idioms":[],"collocations":[],"derivations":["WHO-Büro","WHO-Direktor","WHO-Europabüro","WHO-Klassifikation","WHO-Lösung","WHO-Regionaldirektor","WHO-Schema","WHO-Stufenschema","WHO-Trinklösung"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"WHO","id":"a54f3226786e57"},"0077-0068:cd2c870839c9d8":{"word":"WHG","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"WHG","de-DE":"WHG"},"forms":[],"senses":[{"definition":"Abkürzung für Wasserhaushaltsgesetz"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"WHG","id":"cd2c870839c9d8"},"0077-0068:3a85542d2a63af":{"word":"Whg.","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"Whg.","de-DE":"Whg."},"forms":[],"senses":[{"definition":"Abkürzung für Wohnung"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whg.","id":"3a85542d2a63af"},"0077-0068:8d9eb1974ca041":{"word":"Whitehorse","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"White·hor·se","de-DE":"White·hor·se"},"forms":[{"form":"Whitehorses","tags":["Genitiv","Singular"]},{"form":"des Whitehorse","tags":["Genitiv","Singular"]},{"form":"des Whitehorses","tags":["Genitiv","Singular"]},{"form":"(das) Whitehorse","tags":["Nominativ","Singular"]},{"form":"(dem) Whitehorse","tags":["Dativ","Singular"]}],"senses":[{"definition":"Hauptstadt des kanadischen Yukon-Territoriums"}],"synonyms":[],"origins":[],"examples":[{"text":"Whitehorse liegt im Süden des Territoriums und etwa auf der gleichen geographischen Breite wie Lillehammer in Norwegen.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whitehorse","id":"8d9eb1974ca041"},"0077-0068:38cb1a8643dc61":{"word":"Whisky","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Whis·ky","de-DE":"Whis·ky"},"forms":[{"form":"Whisky","tags":["Nominativ","Singular"]},{"form":"Whiskys","tags":["Nominativ","Plural"]}],"senses":[{"definition":"alkoholisches Getränk, das aus Gerste oder Malz durch Fermentierung und Destillation gewonnen wird"}],"synonyms":[],"origins":["Entlehnung aus dem englischen whisky ^(→ en)"],"examples":[{"text":"Ein Glas Whisky, bitte!","reference":""},{"text":"„Lady Death bekam ihren Whisky, kippte ihn und wandte sich an Céline.“","reference":"Charles Bukowski: Ausgeträumt. Roman. Deutscher Taschenbuch Verlag, München 1997 (übersetzt von Carl Weissner), ISBN 3-423-12342-7, Seite 99. Englisches Original 1994."},{"text":"„Der eine trank Whisky, der andere aß Eis mit Schlagsahne.“","reference":"Johannes Mario Simmel: Es muß nicht immer Kaviar sein. Mit auserlesenen Kochrezepten des Geheimagenten wider Willen. Nikol, Hamburg 2015, ISBN 978-3-86820-292-2, Seite 251. Erstveröffentlichung Zürich 1960."}],"idioms":[],"collocations":[],"derivations":["Whiskyaroma","Whiskybecher","Whiskyflasche","Whiskyglas"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whisky","id":"38cb1a8643dc61"},"0077-0068:aeaa4e321d3dcc":{"word":"Whist","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Whist","de-DE":"Whist"},"forms":[{"form":"Whist","tags":["Nominativ","Singular"]},{"form":"Whiste","tags":["Dativ","Singular"]},{"form":"Whists","tags":["Genitiv","Singular"]},{"form":"Whistes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Kartenspiel aus England für vier Personen mit französischem Blatt (52 Karten), Vorläufer von Bridge"}],"synonyms":[],"origins":["Entlehnung aus dem englischen whist ^(→ en)"],"examples":[{"text":"„Er war ganz Soldat und ging darin auf. Nun hat er nichts zu tun und steht im Tattersall umher oder besucht den Club, ja, fast läßt sich sagen, er lebe da. Vor Tisch liest er Zeitungen, nach Tisch spielt er Whist oder Billard […].“","reference":"Theodor Fontane ^(→ WP): Cécile. In: Projekt Gutenberg-DE. Einundzwanzigstes Kapitel (URL) . Alte Version im Internet-Archiv abrufbar. *"},{"text":"„Der Graf entschloß sich zu einer Partie Whist, und Walpole begann ein Primspiel mit der Gräfin, die offensichtlich mogelte.“","reference":"Giacomo Casanova: Geschichte meines Lebens, herausgegeben und eingeleitet von Erich Loos, Band VI. Propyläen, Berlin 1985 (Neuausgabe) (übersetzt von Heinz Sauter), Seite 9 f."},{"text":"„Und die Frau war ausgegangen, um Karten zu spielen, so eine Art Whist, was sie Bridge nennen, wobei sie einander sagen, was sie in der Hand haben, und dann erst ausspielen.“","reference":"Halldór Laxness: Atomstation. Roman. Rowohlt Taschenbuch Verlag, Hamburg 1955, Seite 33."},{"text":"„Der beste Schachspieler der Christenheit ist vielleicht nicht mehr als eben nur der beste Schachspieler; die Tüchtigkeit und Gewandtheit im Whist lassen aber auf einen feinen Kopf schließen, der überall, wo der Geist mit dem Geist kämpft, des Erfolges sicher sein kann.“","reference":"Edgar Allen Poe: Der Doppelmord in der Rue Morgue. Propyläen-Verlag, Berlin o.J. (übersetzt von Theodor Etzel)"}],"idioms":[],"collocations":[],"derivations":["Whistkarte","Whistpartie","Whistspiel"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whist","id":"aeaa4e321d3dcc"},"0077-0068:1a88c763e335a8":{"word":"Whiteboard","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"White·board","de-DE":"White·board"},"forms":[{"form":"Whiteboard","tags":["Nominativ","Singular"]},{"form":"Whiteboards","tags":["Nominativ","Plural"]}],"senses":[{"definition":"speziell beschichtete Weißwandtafel, auf der man mit speziellen Whiteboard-Markern (Board-Markern) schreiben kann; das Geschriebene lässt sich leicht mit einem trockenen Schwamm abwischen"},{"definition":"elektronische Tafel mit großer Projektionsfläche, die mit einem Computer und Beamer verwendet wird und multimediale Darstellungen ermöglicht, die mithilfe eines Stiftes oder Fingers gesteuert und bearbeitet werden können"}],"synonyms":[],"origins":["Entlehnung aus dem englischen whiteboard ^(→ en)"],"examples":[{"text":"Das Whiteboard ist eine Weiterentwicklung der klassischen, mit Kreide zu beschreibenden Schultafel.","reference":""},{"text":"Permanent-Marker sollte man nicht auf einem Whiteboard verwenden.","reference":""},{"text":"„Er schrieb den Namen des Opfers mit Rotstift auf ein glänzendes Whiteboard.“","reference":"Eva Björg Ægisdóttir: Verschwiegen. Ein Island-Krimi. 1. Auflage. Kiepenheuer & Witsch, Köln 2024 (übersetzt von Freyja Melsted), ISBN 978-3-462-00663-6, Seite 101. Isländisch 2018."},{"text":"Immer mehr Schulen werden mit Whiteboards ausgestattet.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whiteboard","id":"1a88c763e335a8"},"0077-0068:8a1ccb3017de7b":{"word":"Whiskey","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Whis·key","de-DE":"Whis·key"},"forms":[{"form":"Whiskey","tags":["Nominativ","Singular"]},{"form":"Whiskeys","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Whisky, der in Irland oder Amerika aus Roggen oder Mais hergestellt wird"}],"synonyms":[],"origins":[],"examples":[{"text":"„Er stand auf, ließ Hugo und mich im Arbeitszimmer zurück und ging ins Wohnzimmer, wo er sich einen Whiskey aus der Hausbar einschenken würde, einen großen.“","reference":"Edgar Rai: Nächsten Sommer. 3. Auflage. Aufbau Verlag, Berlin 2011, ISBN 978-3-7466-2732-8. , Seite 56."},{"text":"„Grenfeld orderte mit einer seit Jahren eingeübten Handbewegung zwei Whiskeys und hoffte auf die einsetzende Redseligkeit seines Kollegen.“","reference":"Robert Baur: Blutmai. Roman. Gmeiner, Meßkirch 2018, ISBN 978-3-8392-2290-4, Seite 95."},{"text":"„Ich war nie die Schlankeste, aber bei dieser ewigen Nudelkost habe ich angesetzt. Allerdings gab es da noch mehr, wenn ich ehrlich bin, kistenweise Schokolade, Kekse und andere Süßigkeiten, und ja, auch Alkohol, sogar harter Stoff, Whiskey, Gin, Wodka“","reference":"Bernhard Kegel: Gras. Dörlemann, Zürich 2023, ISBN 978-3-03820-138-0, Seite 24."},{"text":"„Sie zwinkerte mir zu und verschwand nach oben, und ich kaute auf meinem Bleistift herum und stellte mir Amalia als junge Frau vor mit feuerrotem Haar und kehligem Lachen, die mit wildfremden Männern in französischen Bars Whiskey trank und wusste, wie man Verletzungen verband und Freundschaften knüpfte.“","reference":"Elisabeth Beer: Die Bücherjägerin. Roman. 1. Auflage. DuMont, Köln 2023, ISBN 978-3-8321- 6638-0 , Seite 113."}],"idioms":[],"collocations":[],"derivations":["Whiskeyaroma","Whiskeyfahne","Whiskeyflasche","Whiskeyglas","Whiskeykäufer","Whiskeyschmuggler","Whiskeyverkäufer"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whiskey","id":"8a1ccb3017de7b"},"0077-0068:c5842d8690c559":{"word":"Whistleblowing","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Whist·le·b·lo·wing","de-DE":"Whist·le·b·lo·wing"},"forms":[{"form":"Whistleblowing","tags":["Nominativ","Singular"]},{"form":"Whistleblowings","tags":["Genitiv","Singular"]}],"senses":[{"definition":"das Aufdecken und Enthüllen von brisanten, von der Allgemeinheit nicht tolerierbaren Fehlverhaltensweisen einzelner Individuen in Organisationen und Unternehmen wie Korruption, Forschungsfälschung, Diebstahl geistigen Eigentums etc. im Sinne der Allgemeinheit"}],"synonyms":[],"origins":["abgeleitet von der englischen Redewendung: \"to blow the whistle on someone\" (deutsch: \"jemanden verpfeifen\"). Die in Frage stehende Verhaltensvariante wurde zunächst 1963 in den Vereinigten Staaten so bezeichnet und ging im Zusammenhang mit juristischen Diskussionen zu diesem Thema in den deutschen Sprachgebrauch über."],"examples":[{"text":"„Institutionen brauchen eigene Whistleblower-Regelungen […]. Denn Whistleblowing ist ein Fremdwort, dessen Erscheinen hierzulande neben einer Aufmerksamkeitsverschiebung auch einen internationalen Wissenstransfer im Recht signalisiert.“","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whistleblowing","id":"c5842d8690c559"},"0077-0068:22cf738877c15c":{"word":"Whiskyflasche","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Whis·ky·fla·sche","de-DE":"Whis·ky·fla·sche"},"forms":[{"form":"Whiskyflasche","tags":["Nominativ","Singular"]},{"form":"Whiskyflaschen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Flasche, in der Whisky aufbewahrt wird"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Whisky und Flasche"],"examples":[{"text":"In jedem Spirituosengeschäft kann man Whiskyflaschen finden.","reference":""},{"text":"„Sie saßen ganz vorn und ließen eine Whiskyflasche hin und her wandern.“","reference":"Henning Mankell: Der Sandmaler. Roman. Paul Zsolnay Verlag, München 2017, ISBN 978-3-552-05854-5, Seite 30. Schwedisches Original 1974."},{"text":"„Max Schulz stieß Frau Holle ärgerlich mit der leeren Whiskyflasche an, woraufhin Frau Holle erschreckt die Augen aufriß.“","reference":"Edgar Hilsenrath: Der Nazi & der Friseur. Roman. 15. Auflage. dtv, München 2017, ISBN 978-3-423-13441-5, Seite 171. Zuerst 1977 erschienen."},{"text":"„Er hatte bei diesen Worten eine kleine Whiskyflasche aus seiner wollenen Decke herausgewickelt, drehte, während er lächelnd nach Rowson hinübernickte, den Stöpsel heraus und setzte sie dann mit einem sehr selbstzufriedenen »Prost« an die Lippen.“","reference":"Friedrich Gerstäcker: Die Regulatoren in Arkansas. Ein Roman aus dem amerikanischen Pflanzerleben. Fischer Taschenbuch Verlag, Frankfurt am Main 1975, Seite 8. Zuerst 1845 erschienen."},{"text":"„Sie gingen in die Küche, woselbst sich der Lohn der verkauften Souvenirs in Form von Konservendosen, Fleisch und Whiskyflaschen präsentierte.“","reference":"Johannes Mario Simmel: Es muß nicht immer Kaviar sein. Mit auserlesenen Kochrezepten des Geheimagenten wider Willen. Nikol, Hamburg 2015, ISBN 978-3-86820-292-2, Seite 623. Erstveröffentlichung Zürich 1960."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whiskyflasche","id":"22cf738877c15c"},"0077-0068:ef3c4056e5342b":{"word":"Whiskeyflasche","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Whis·key·fla·sche","de-DE":"Whis·key·fla·sche"},"forms":[{"form":"Whiskeyflasche","tags":["Nominativ","Singular"]},{"form":"Whiskeyflaschen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Flasche, in der Whiskey ist"}],"synonyms":[],"origins":[],"examples":[{"text":"„Dann reichten wir die Whiskeyflasche herum und wärmten uns damit.“","reference":"James Carlos Blake: Pistolero. Liebeskind, München 2015, ISBN 978-3-95438-051-0, Seite 112 ."},{"text":"„Vor ihm auf dem Tisch standen eine halb leere Whiskeyflasche und ein Glas.“","reference":"Jón Atli Jónasson: Schmerz. Ein Fall für Dora und Rado. 2. Auflage. Scherz, Frankfurt/Main 2024 (übersetzt von Freyja Melsted), ISBN 978-3-651-00134-3, Seite 10. Isländisches Original Reykjavík 2022."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whiskeyflasche","id":"ef3c4056e5342b"},"0077-0068:bfca1c18e834f5":{"word":"Whitby","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Whit·by","de-DE":"Whit·by"},"forms":[{"form":"Whitbys","tags":["Genitiv","Singular"]},{"form":"des Whitby","tags":["Genitiv","Singular"]},{"form":"des Whitbys","tags":["Genitiv","Singular"]},{"form":"(das) Whitby","tags":["Nominativ","Singular"]},{"form":"(dem) Whitby","tags":["Dativ","Singular"]}],"senses":[{"definition":"Kleinstadt in Nordengland"},{"definition":"Stadt in der kanadischen Provinz Ontario"}],"synonyms":[],"origins":[],"examples":[{"text":"„Seltsam ist der Name des Dorfes Crow-on-Sea, das südlich der Abtei von Whitby liegt.“","reference":"Eliza Clark: Penance. Festa, Leipzig 2025, ISBN 978-3-986-76240-7, Seite 55 ."},{"text":"„Als sie fragen, sagt er ihnen, dass sein Name Peter Batchelor ist und er sich auf dem Weg von York nach Whitby befindet, wo sein Onkel krank geworden ist und möglicherweise im Sterben liegt.“","reference":"Ian McGuire: Nordwasser. Mare, Hamburg 2018, ISBN 978-3-86648-267-8, Seite 246 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whitby","id":"bfca1c18e834f5"},"0077-0068:72a935bb64cb28":{"word":"Whitehall","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"White·hall","de-DE":"White·hall"},"forms":[{"form":"Whitehalls","tags":["Genitiv","Singular"]},{"form":"des Whitehall","tags":["Genitiv","Singular"]},{"form":"des Whitehalls","tags":["Genitiv","Singular"]},{"form":"(das) Whitehall","tags":["Nominativ","Singular"]},{"form":"(dem) Whitehall","tags":["Dativ","Singular"]}],"senses":[{"definition":"Straße in London im Regierungsviertel Westminster"}],"synonyms":[],"origins":[],"examples":[{"text":"„›Ich bin zwar keine Agentin für operative Einsätze, aber ich bin gerade in Whitehall, keine fünf Minuten von Ihnen entfernt.‹“","reference":"Mark Greaney: The Gray Man - Geheimcode Poison Apple. Festa, Leipzig 2025, ISBN 978-3-98676-197-4, Seite 458 ."},{"text":"„Der große graue Block von Whitehall, wo die britische Regierung saß, lag knapp zwei Kilometer entfernt versteckt hinter den hohen Gebäuden am Flussufer.“","reference":"David Ignatius: Der Einsatz. Rowohlt, Reinbek bei Hamburg 2010, ISBN 978-3-499-25291-4, Seite 119 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whitehall","id":"72a935bb64cb28"},"0077-0068:1c24100d3216fa":{"word":"wh.","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"wh.","de-DE":"wh."},"forms":[],"senses":[{"definition":"wohnhaft"},{"definition":"wiederholt"},{"definition":"wechselhaft"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"wh.","id":"1c24100d3216fa"},"0077-0068:63129f0a4f0c37":{"word":"Whig","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Whig","de-DE":"Whig"},"forms":[{"form":"Whig","tags":["Nominativ","Singular"]},{"form":"Whigs","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Anhänger einer politischen Gruppierung im englischen Parlament"},{"definition":"Anhänger oder Sympathisant einer liberalen politischen Ausrichtung in England"}],"synonyms":[],"origins":["Entlehnung aus dem englischen Whig ^(→ en)"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whig","id":"63129f0a4f0c37"},"0077-0068:61f133ad6da6a6":{"word":"Whistleblower","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Whist·le·b·lower","de-DE":"Whist·le·b·lower"},"forms":[{"form":"Whistleblower","tags":["Nominativ","Singular"]},{"form":"Whistleblowern","tags":["Dativ","Plural"]},{"form":"Whistleblowers","tags":["Genitiv","Singular"]},{"form":"Whistleblowerin","tags":["feminine"]}],"senses":[{"definition":"(männliche^☆) Person, die Missstände oder Gesetzwidrigkeiten (an ihrem Arbeitsplatz) an die Öffentlichkeit bringt; (männliche^☆) Person, die Whistleblowing betreibt"}],"synonyms":["Denunziant","Hinweisgeber","Informant","Konfident","Kontaktmann","Kundschafter","Polizeiinformant","Polizeispitzel","Singvogel","V-Mann","V-Person","Verbindungsmann","Verbindungsperson","Vigilant","Zuträger"],"origins":["Es handelt sich um eine Entlehnung aus gleichbedeutend englischem whistle-blower ^(→ en), das seinerseits eine Ableitung zu der Redewendung to blow the whistle ^(→ en) ‚pfeifen; übertragen: anzeigen, verpfeifen‘ ist und also eigentlich ‚Pfeifer, Verpfeifer‘ bedeutet."],"examples":[{"text":"„Was ist im modernen amerikanischen Slang ein ‚Whistleblower‘? Ein Musiker? Eine Vogelart? Ein technisches Gerät? Nichts von alledem. Unter einem Whistleblower - wörtlich: Pfeifenbläser - versteht man einen verantwortungsbewußten Wissenschaftler, Ingenieur oder Techniker, der die Öffentlichkeit rechtzeitig davor warnt, wenn in seinem speziellen Fachbereich eine Entwicklung verfolgt wird, die auf die eine oder andere Weise Schaden bringen kann.“","reference":"Anatol Johansen: Warnenden Wissenschaftlern droht ein Karriere-Knick. Unzureichender Schutz für Forscher in Deutschland. In: Frankfurter Rundschau. 3. Mai 1997, Seite 8 ."},{"text":"„Whistleblower sind Menschen, die frühzeitig auf Probleme und Bedrohungen unserer Gesellschaft aufmerksam machen. Leute also, die die Alarmpfeife blasen.“","reference":"Johannes Pfeuffer: …. In: Frankfurter Rundschau. 27. September 1997, Seite 8 ."},{"text":"„Die Bundesregierung plant eine Regelung zum Schutz von sogenannten ‚Whistleblowern‘.“","reference":"„Verpfeifen“ ohne Angst um Job. In: Hannoversche Allgemeine. 22. Mai 2008, Seite 11 ."},{"text":"„Aber in Deutschland scheiterte bisher selbst der erste zaghafte Schritt, die Rechtslage für Whistleblower durch eine Regelung im Bürgerlichen Gesetzbuch zu verbessern.“","reference":"Mit neuen Regeln gegen Korruption in Firmen: Experten fordern Sicherheit für Hinweisgeber. Angst vor Repressalien bewahrt „Kultur des Schweigens“. In: Nürnberger Nachrichten. 4. Juni 2009, Seite 4 ."},{"text":"„Zudem wäre es auch an der Zeit, wenn im Interesse aller die rechtlichen Schutznormen für «Whistleblower» endlich verbessert würden!“","reference":"Y. Stadler: «Tötet den Boten!» In: St. Galler Tagblatt. Nummer 214, 15. September 2009, Seite 29 ."},{"text":"„Die Informanten werden auch ‚Whistleblower‘ (Tippgeber) genannt.“","reference":"dpa: Die Plattform für geheime Dokumente. In: Hamburger Abendblatt. 1. Dezember 2010 (URL, abgerufen am 7. Dezember 2014) ."},{"text":"„Es wird häufig mit Illoyalität, Denunziantentum oder sogar Geheimnisverrat assoziiert und endet nicht selten mit einer Sanktionierung des Whistleblowers (Mobbing, Bedrohung, Entlassung oder strafrechtliche Verfolgung).“","reference":"Whistleblower: Helden oder Denunzianten? In: St. Galler Tagblatt. Nummer 105, 5. Mai 2012, Seite 2 ."},{"text":"„Und seit Obama Präsident ist, hat sich auch die strafrechtliche Verfolgung von Whistleblowern, von Leuten, die Informationen aus der Regierung nach außen geben, intensiviert.“","reference":"Jon Wiener: Als die USA noch ein anderes Land waren. Acht Gründe, dem Kalten Krieg nachzutrauern. In: Le Monde diplomatique Online. Deutschsprachige Ausgabe. Nummer 10051, 8. März 2013 (übersetzt von Niels Kadritzke), ISSN 1434-2561 (URL, abgerufen am 7. Dezember 2014) ."},{"text":"„Die spektakuläre Flucht des sogenannten Whistleblowers sorgt für erhebliche politische Spannungen.“","reference":"Politkrimi um US-Informant Snowden. In: Mannheimer Morgen. 26. Juni 2013, Seite 1 ."},{"text":"„Die unnachsichtige Kriminalisierung von Whistleblowern soll offensichtlich dazu dienen, potenzielle Quellen für eine kritische Berichterstattung über den Missbrauch staatlicher Macht durch Strafandrohung systematisch trockenzulegen.“","reference":"REPORTER OHNE GRENZEN FÜR PRESSEFREIHEIT: Meldungen des Monats. Schlechte Nachrichten. In: Le Monde diplomatique Online. Deutschsprachige Ausgabe. Nummer 10178, 9. August 2013, ISSN 1434-2561 (URL, abgerufen am 7. Dezember 2014) ."}],"idioms":[],"collocations":[],"derivations":["Whistleblowerin"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Whistleblower","id":"61f133ad6da6a6"},"0077-0068:4776647740b94f":{"word":"Whisker","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Whis·ker","de-DE":"Whis·ker"},"forms":[{"form":"Whisker","tags":["Nominativ","Singular"]},{"form":"Whiskern","tags":["Dativ","Plural"]},{"form":"Whiskers","tags":["Nominativ","Plural"]}],"senses":[{"definition":"äußerst feiner, fadenartiger Monokristall, der organisch oder anorganisch gewachsen ist und sehr zugfest ist"},{"definition":"Bestandteil eines Boxplots, der sich außerhalb der Box befindet und dessen Länge meist das 1,5-Fache des Interquartilsabstandes beträgt"}],"synonyms":[],"origins":["Entlehnung aus dem englischen whisker ^(→ en)"],"examples":[{"text":"„Ist der Boxplot symmetrisch – liegt der Median also in der Mitte der Box und sind die Whiskers vergleichsweise gleich lang – liegt eine symmetrische Verteilung vor.“","reference":"Thomas Cleff: Deskriptive Statistik und moderne Datenanalyse. Eine computergestützte Einführung mit Excel, PASW (SPSS) und STATA. 2. Auflage. Springer Verlag, Wiesbaden 2012, ISBN 978-3-8349-7071-8, Seite 57 (zitiert nach Google Books)"},{"text":"„Wie man erkennt, liegen keine Ausreißer vor, sodass die Whisker bis zur kürzesten Zeit von 62,6 s bzw. längsten Zeit von 148,2 s reichen.“","reference":"Jürgen Bortz/Christof Schuster: Statistik für Human- und Sozialwissenschaftler. Lehrbuch mit Online-Materialien. 7. Auflage. Springer Verlag, Berlin/Heidelberg 2010, ISBN 978-3-642-12770-0, Seite 45 (zitiert nach Google Books)"},{"text":"„Durch die Whisker werden die außerhalb der Box liegenden Werte dargestellt.“","reference":"Carsten Kühnel: Verkehrsdatenerfassung mittels Floating Car Observer auf zweistreifigen Landstraßen. kassel university press, Kassel 2012, ISBN 978-3-86219-418-6, Seite 215 (zitiert nach Google Books)"},{"text":"„Darüber hinaus sind bei asymmetrischen Daten die Whisker nicht gleich lang.“","reference":"Michael Falk u.a.: Statistik in Theorie und Praxis. Mit Anwendungen in R. Springer Verlag, Berlin 2014, ISBN 978-3-642-55252-6, Seite 26 (zitiert nach Google Books)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whisker","id":"4776647740b94f"},"0077-0068:eec9eb92583b38":{"word":"Whitworthgewinde","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Whit·wort·h·ge·win·de","de-DE":"Whit·wort·h·ge·win·de"},"forms":[{"form":"Whitworthgewinde","tags":["Nominativ","Singular"]},{"form":"Whitworth-Gewinde","tags":["alternative"]},{"form":"Whitworthgewinden","tags":["Dativ","Plural"]},{"form":"Whitworthgewindes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Schraubengewinde, das genormt ist und in Zoll gemessen wird"}],"synonyms":[],"origins":["benannt nach dem britischen Ingenieur Sir Joseph Whitworth"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whitworthgewinde","id":"eec9eb92583b38"},"0077-0068:fb7958843c656f":{"word":"White-Collar-Kriminalität","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"White-Col·lar-Kri·mi·na·li·tät","de-DE":"White-Col·lar-Kri·mi·na·li·tät"},"forms":[{"form":"White-collar-Kriminalität","tags":["obsolete"]}],"senses":[{"definition":"nicht gewalttätige strafbare Handlung, die weniger offensichtliche ist und von Personen aus höheren sozialen Schichten, wie Politik, Wirtschaft, Industrie, begangen wird"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"White-Collar-Kriminalität","id":"fb7958843c656f"},"0077-0068:011bc0676e1626":{"word":"Whistler","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Whist·ler","de-DE":"Whist·ler"},"forms":[{"form":"Whistler","tags":["Nominativ","Singular"]},{"form":"Whistlern","tags":["Dativ","Plural"]},{"form":"Whistlers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"elektromagnetische Welle, die von Blitzen in der Troposphäre ausgesendet werden und entlang der magnetischen Feldlinien der Erde den Raum durchlaufen"}],"synonyms":[],"origins":["Entlehnung aus dem englischen whistler ^(→ en)"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whistler","id":"011bc0676e1626"},"0077-0068:6f41a34c57a4b3":{"word":"Whirlpool","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Whirl·pool","de-DE":"Whirl·pool"},"forms":[{"form":"Whirlpool","tags":["Nominativ","Singular"]},{"form":"Whirlpools","tags":["Nominativ","Plural"]}],"senses":[{"definition":"kleines Wasserbecken mit warmen Wasser, das angesaugt und unterhalb der Wasseroberfläche unter hohem Druck wieder zurückgeströmt wird, wodurch ein Sprudel entsteht"}],"synonyms":["Jacuzzi","Sprudelbad"],"origins":["Entlehnung aus dem englischen whirlpool ^(→ en)"],"examples":[{"text":"Gestern Abend saß ich mit meiner Verlobten im Whirlpool und wir tranken Wein.","reference":""},{"text":"„Dafür gibt es kein Schwimmbecken und keinen Whirlpool, keinen Fitnessraum und keine Tischtennisplatte.“","reference":"Björn Kuhligk, Tom Schulz: Rheinfahrt. Ein Fluss. Seine Menschen. Seine Geschichten. Orell Füssli, Zürich 2017, ISBN 978-3-280-05630-1, Seite 296."},{"text":"„Da gab's dann bald mehr Diskos als Kühe in den Dörfern, in den Landgasthöfen sprudelten die Whirlpools, und die Sennerinnen wurden mit dem Paragleiter auf die Alm geflogen.“","reference":"Rosemarie Noack: Come back. In: Zeit Online. 7. März 1997, ISSN 0044-2070 (URL) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Whirlpool","id":"6f41a34c57a4b3"},"0077-0068:323bed584ee605":{"word":"Whip","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Whip","de-DE":"Whip"},"forms":[{"form":"Whip","tags":["Nominativ","Singular"]},{"form":"Whips","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Abgeordneter im britischen Unterhaus, der die Arbeit seiner Fraktion koordiniert und für die Anwesenheit seiner Parteimitglieder sowie für Ruhe und Ordnung bei Sitzungen zu sorgen hat"}],"synonyms":[],"origins":["Entlehnung aus dem englischen whip ^(→ en)"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whip","id":"323bed584ee605"},"0077-0068:18676b0004b84e":{"word":"Whipcord","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Whip·cord","de-DE":"Whip·cord"},"forms":[{"form":"Whipcord","tags":["Nominativ","Singular"]},{"form":"Whipcords","tags":["Nominativ","Plural"]}],"senses":[{"definition":"kräftiges Gewebe aus Kammgarn, das schräg gerippt ist und"}],"synonyms":[],"origins":["Entlehnung aus dem englischen whipcord ^(→ en)"],"examples":[{"text":"Sie trug einen Rock aus Whipcord.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whipcord","id":"18676b0004b84e"},"0077-0068:3a313af4e22ed7":{"word":"Wheatstonebrücke","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Wheatston·ebrü·cke","de-DE":"Wheatston·ebrü·cke"},"forms":[{"form":"Wheatstonebrücke","tags":["Nominativ","Singular"]},{"form":"Wheatstone-Brücke","tags":["alternative"]},{"form":"Wheatstonebrücken","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Brückenschaltung, mit deren Hilfe elektrische Widerstände gemessen werden können"}],"synonyms":[],"origins":["benannt nach dem britischen Physiker Sir Charles Wheatstone"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Wheatstonebrücke","id":"3a313af4e22ed7"},"0077-0068:b26f73d888c329":{"word":"Wheelie","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Whee·lie","de-DE":"Whee·lie"},"forms":[{"form":"Wheelie","tags":["Nominativ","Singular"]},{"form":"Wheelies","tags":["Nominativ","Plural"]}],"senses":[{"definition":"beim Fahren das Vorderrad/die Vorderräder den Boden nicht berühren lassen"}],"synonyms":[],"origins":["von gleichbedeutend englisch wheelie ^(→ en) entlehnt, das auf wheel ^(→ en) „Rad“ zurückgeht"],"examples":[{"text":"Ich kann mit dem Fahrrad einen Wheelie machen.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Wheelie","id":"b26f73d888c329"},"0077-0068:65a7684de6fac6":{"word":"WHK","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"WHK","de-DE":"WHK"},"forms":[],"senses":[{"definition":"wissenschaftliche Hilfskraft"},{"definition":"Welthandelskonferenz"},{"definition":"Wasserhaltekapazität"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"WHK","id":"65a7684de6fac6"},"0077-0068:b904e096d29d9d":{"word":"Whistleblowerin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Whist·le·b·lo·we·rin","de-DE":"Whist·le·b·lo·we·rin"},"forms":[{"form":"Whistleblower","tags":["masculine"]},{"form":"Whistleblowerin","tags":["Nominativ","Singular"]},{"form":"Whistleblowerinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Frau, die Missstände oder Gesetzwidrigkeiten (an ihrem Arbeitsplatz) an die Öffentlichkeit bringt; Frau, die Whistleblowing betreibt"}],"synonyms":[],"origins":["Ableitung (Motion, Movierung) des Femininums aus der männlichen Form Whistleblower mit dem Derivatem (Ableitungsmorphem) -in"],"examples":[{"text":"„Die Whistleblowerin sitzt im Militärgefängnis Fort Leavenworth im US-Bundesstaat Kansas ein, wo besonders harsche Regeln gelten.“","reference":"Janko Tietz/mja/Reuters/Deutsche Presse-Agentur: WikiLeaks: Obama lässt Whistleblowerin Chelsea Manning im Mai frei. In: Spiegel Online. 18. Januar 2017, ISSN 0038-7452 (URL, abgerufen am 18. Januar 2017) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whistleblowerin","id":"b904e096d29d9d"},"0077-0068:1f7b2eb2ab13ae":{"word":"Whataboutism","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"What·a·bou·tism","de-DE":"What·a·bou·tism"},"forms":[{"form":"Whataboutism","tags":["Nominativ","Singular"]},{"form":"Whataboutisms","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Argumentationstechnik, bei der man auf einen kritischen Vorwurf über ein Versagen mit einem Verweis auf ein Fehlverhalten oder einen Missstand auf der anderen Seite, zum Beispiel der des Gesprächspartners, verweist"}],"synonyms":["(Antwort mit einer) Gegenfrage","Tu-quoque-Argument"],"origins":["mit gleicher Bedeutung aus dem Englischen: whataboutism ^(→ en)"],"examples":[{"text":"„‚Whataboutism‘ bezeichnet das Phänomen, eine Anschuldigung oder eine Frage in einer Diskussion mit einer Gegenfrage oder einem Themawechsel zu erwidern.“","reference":"Böhmermann provoziert Dresden, Sächsische Zeitung. Abgerufen am 21. Juli 2017."},{"text":"„Donald Trump beherrscht ihn perfekt und auch viele Diskutanten in den sozialen Medien: Mit \"Und was ist mit…?\" kann man jede Debatte torpedieren und als Sieger hervorgehen. Doch die Strategie des Whataboutism lässt sich auch entlarven.“","reference":"Fehlender Parameter (Hilfe) Abgerufen am 21. Juli 2017."},{"text":"„Ein Beispiel ist der sogenannte Whataboutism, über den viele Menschen stolz sind, ihn vor einigen Jahren entdeckt zu haben. Die Argumentation mit Whataboutism ist mir grundsätzlich verdächtig, weil sie eine Diskussion abschneidet.“","reference":"Fehlender Parameter (Hilfe) Abgerufen am 21. Juli 2017."},{"text":"„Damals hieß das noch nicht Whataboutism, sondern »Tu quoque«. So nennt man den Versuch, ein Argument zu entkräften, indem man dem Gegner das gleiche Verhalten vorwirft.“","reference":"Fehlender Parameter (Hilfe) Abgerufen am 21. Juli 2017."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Whataboutism","id":"1f7b2eb2ab13ae"},"0077-0068:547c68adfc5233":{"word":"Whataboutismus","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"What·a·bou·tis·mus","de-DE":"What·a·bou·tis·mus"},"forms":[{"form":"Whataboutismus","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Argumentationstechnik, bei der man auf einen kritischen Vorwurf über ein Versagen mit einem Verweis auf ein Fehlverhalten oder einen Missstand auf der anderen Seite, zum Beispiel der des Gesprächspartners, verweist"}],"synonyms":[],"origins":["Eindeutschung des ins Deutsche übernommenen Ausdrucks Whataboutism, der seinerseits mit gleicher Bedeutung aus dem Englischen kommt: whataboutism ^(→ en)"],"examples":[{"text":"„Kürzlich wurde mir im Netz \"Whataboutismus\" vorgeworfen. Ich hatte keine Ahnung, was das ist, obwohl es nur zwei Monate vorher in einem Leitartikel der ZEIT erklärt worden war.“","reference":"Über rhetorische Ausweichmanöver, Harald Martenstein, Zeitmagazin. Abgerufen am 21. Juli 2017."},{"text":"„Martenstein berichtet über Whataboutismus. Dieser neudeutsche Begriff beschreibt eine beliebte Ablenkung in Debatten: Sobald eine Diskussions-Partei einer anderen eine Verfehlung vorwirft, kontert diese mit dem Argument „aber was ist denn mit XY.“ XY steht dabei für einen beliebigen Fehltritt des Gesprächspartners.“","reference":"Was ist eigentlich … Whataboutismus? 100woerter.de. Abgerufen am 21. Juli 2017."},{"text":"„Genannt wird dieses Muster \"Whataboutismus\". Der Begriff stammt von der englischen Frage \"What about…?\", was auf Deutsch bedeutet: \"Und was ist mit…?\" Beklagt jemand zum Beispiel die Zunahme von Rechtsextremismus, heißt es nur allzu oft: \"Und was ist mit den Linken?\" – als ob das rechtsextreme Gewalt irgendwie besser machen würde.“","reference":"Fehlender Parameter (Hilfe) Abgerufen am 21. Juli 2017."},{"text":"„„Guck mal, Dresden, Hauptstadt des Whataboutismus: Das ist Köln 1945. 70% kaputt. 20.000 Tote allein durch Luftangriffe. Und keiner jammert“, schrieb der 35-Jährige am Montag zu einem Foto des von Bomben zerstörten Köln.“","reference":"Böhmermann provoziert Dresden, Sächsische Zeitung. Abgerufen am 21. Juli 2017."},{"text":"„Das, was ich hier tue, nennt man Whataboutismus. Auf eine Frage gibt es eine Gegenfrage, ein what about, ein was ist mit, sozusagen ein Ausweichmanöver, das von der Ausgangsfrage ablenken soll.“","reference":"Fehlender Parameter (Hilfe) Abgerufen am 21. Juli 2017."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whataboutismus","id":"547c68adfc5233"},"0077-0068:56cfc6086cf1ab":{"word":"Whatsapp","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Whats·app","de-DE":"Whats·app"},"forms":[{"form":"WhatsApp","tags":["alternative"]},{"form":"Whatsapps","tags":["Nominativ","Plural"]}],"senses":[{"definition":"eine gegebenenfalls mit Bildern oder Videos versehene Kurzmitteilung, die über den Nachrichtendienst WhatsApp an das Smartphone anderer angemeldeter Benutzer versendet wird"}],"synonyms":[],"origins":["aus dem Englischen, dort gebildet von englisch what's up und app","das Wort ist im Deutschen ein Neologismus der 2010er Jahre","mit Bezug auf WhatsApp Inc.: die Firma, die die Software/Anwendung entwickelt hat und den Dienst anbietet"],"examples":[{"text":"„Nur kurz noch Mails checken, nur die eine Whatsapp beantworten ... und plötzlich war man schon wieder 20 Minuten online.“","reference":"Hamburger Morgenpost, 03.03.2014); zitiert nach: Online-Wortschatz-Informationssystem Deutsch – elexiko „Whatsapp“"},{"text":"Ich habe eben eine Whatsapp von meinem Freund erhalten.","reference":""}],"idioms":[],"collocations":[],"derivations":["whatsappen"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whatsapp","id":"56cfc6086cf1ab"},"0077-0068:6b939372cb057a":{"word":"Whiskyglas","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Whis·ky·glas","de-DE":"Whis·ky·glas"},"forms":[{"form":"Whiskyglas","tags":["Nominativ","Singular"]},{"form":"Whiskeyglas","tags":["alternative"]},{"form":"Whiskyglase","tags":["Dativ","Singular"]},{"form":"Whiskyglases","tags":["Genitiv","Singular"]},{"form":"Whiskygläser","tags":["Nominativ","Plural"]},{"form":"Whiskygläsern","tags":["Dativ","Plural"]}],"senses":[{"definition":"bestimmtes Glas, in dem Whisky gereicht, aus dem er getrunken wird"}],"synonyms":["Tumbler"],"origins":["Determinativkompositum aus den Substantiven Whisky und Glas"],"examples":[{"text":"„Ich nehme mir ein Whiskyglas, ein bauchiges, das sich nach oben hin verengt, gieße mir daumenbreit ein und stelle das Glas neben die Wanne.“","reference":"Peter Dausend: Der Drink: Lagavulin. Die Lage: Badewanne. In: DIE ZEIT. Nummer 04/2016, 4. Februar 2016, ISSN 0044-2070 (Archiv-URL, abgerufen am 19. April 2019) ."},{"text":"„Vorsichtig machte er seinen Arm frei, lichtete sich auf und streckte die Hand nach seinem Whiskyglase aus.“","reference":"Gustav Johannes Wied: Die Väter haben Herlinge gegessen. In: Projekt Gutenberg-DE. Kapitel 29: Nacht. In der Villa Seemann (URL) . Alte Version im Internet-Archiv abrufbar. *"},{"text":"„Whiskygläser in der Hand, Pfeifen im Mund, vor dem flackernden Kaminfeuer sitzend, so hörten die Clubmitglieder jeden Donnerstagabend die tollen Geschichten an, die reihum erzählt wurden.“","reference":"Johannes Mario Simmel: Es muß nicht immer Kaviar sein. Mit auserlesenen Kochrezepten des Geheimagenten wider Willen. Nikol, Hamburg 2015, ISBN 978-3-86820-292-2, Seite 40. Erstveröffentlichung Zürich 1960."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Whiskyglas","id":"6b939372cb057a"},"0077-0068:1d12465b95f891":{"word":"Whiteout","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"White·out","de-DE":"White·out"},"forms":[{"form":"Whiteout","tags":["Nominativ","Singular"]},{"form":"Whiteouts","tags":["Nominativ","Plural"]}],"senses":[{"definition":"meteorologische Erscheinung, bei der durch hohe Helligkeit Boden und Himmel zu verschmelzen scheinen und der Horizont nicht mehr zu erkennen ist"}],"synonyms":[],"origins":[],"examples":[{"text":"„Beim polaren Whiteout wird Sonnenlicht so diffus von der Schnee- und Wolkendecke reflektiert, dass sich im Auge des geblendeten Betrachters bestimmte Kontraste auflösen.“","reference":"Sabine Frost: Whiteout. transcript Verlag, 2014, ISBN 978-3-8394-1884-0 (Zitiert nach Google Books)"},{"text":"„Ein sogenanntes ‚Whiteout‘ soll sich durch die aufwirbelnden Schneewolken entwickelt haben, die Sicht sei dadurch erheblich eingeschränkt gewesen.“","reference":"Kerstin Gehrke: Geldstrafe für den Piloten. In: Der Tagesspiegel Online. 9. Oktober 2017 (URL, abgerufen am 2. August 2021) ."},{"text":"„Denn der ständige Wind, heftige Schneestürme, schlechte Sicht und Whiteout – durch extreme Helligkeit gehen Konturen in Eis und Schnee verloren – machen jeden Flug zum Wagnis.“","reference":"Agnes Schönberger: Der fliegende Bierbrauer. In: FAZ.NET. 9. August 2011 (URL, abgerufen am 2. August 2021) ."},{"text":"„‚Whiteout‘ wird es genannt, wenn in arktischen Eiswüsten nicht mehr erkannt werden kann, wo der Boden endet und der Himmel beginnt – und sich ein unendlich leerer Raum aufzutun scheint.“","reference":"Albert Schäffer: Ein Hauch von Kreuth. In: FAZ.NET. 25. September 2017 (URL, abgerufen am 2. August 2021) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whiteout","id":"1d12465b95f891"},"0077-0068:7d1f0e711d10f0":{"word":"Whiskybecher","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Whis·ky·be·cher","de-DE":"Whis·ky·be·cher"},"forms":[{"form":"Whiskybecher","tags":["Nominativ","Singular"]},{"form":"Whiskeybecher","tags":["alternative"]},{"form":"Whiskybechern","tags":["Dativ","Plural"]},{"form":"Whiskybechers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Becher für/mit Whisky"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Whisky und Becher"],"examples":[{"text":"„Das Abendessen, das vorher durch den schnellen Aufruf zum Rudern unterbrochen worden war, wurde jetzt beendet, wobei der Whiskybecher fleißig im Kreis herumging; die Mannschaft schien sich überhaupt mit einer solchen Leuten eigenen Sorglosigkeit fröhlicher Stimmung hinzugeben.“","reference":"Friedrich Gerstäcker: Die Flußpiraten des Mississippi. Goldmann, München 1964, Seite 202. Zuerst 1848 erschienen."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whiskybecher","id":"7d1f0e711d10f0"},"0077-0068:b77a526396af07":{"word":"Whitechapel","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Whitecha·pel","de-DE":"Whitecha·pel"},"forms":[{"form":"Whitechapels","tags":["Genitiv","Singular"]},{"form":"des Whitechapel","tags":["Genitiv","Singular"]},{"form":"des Whitechapels","tags":["Genitiv","Singular"]},{"form":"(das) Whitechapel","tags":["Nominativ","Singular"]},{"form":"(dem) Whitechapel","tags":["Dativ","Singular"]}],"senses":[{"definition":"Stadtteil von London"}],"synonyms":[],"origins":[],"examples":[{"text":"„Unsere Gänge führten in zwanzig Jahren so oft nach Whitechapel, wo die Bürde der Unglücklichen zum ersten Mal mein Herz peinigte.“","reference":"Alan Moore: From Hell. Ein Melodrama in sechzehn Teilen. Cross Cult, Asperg 2008, ISBN 978-3-936-48053-5, Seite 42 ."},{"text":"„Ein weiterer Verbündeter war der Gewerkschaftsführer Ernest Bevin, der angesichts einer bevorstehenden Wahl im Londoner Stadtteil Whitechapel um die Stimmen des beträchtlichen jüdischen Bevölkerungsanteils fürchtete.“","reference":"Tom Segev: Es war einmal ein Palästina. Juden und Araber vor der Staatsgründung Israels. Siedler, München 2005, ISBN 978-3-886-80805-2, Seite 367 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whitechapel","id":"b77a526396af07"},"0077-0068:93a8a15659502c":{"word":"Whiskeyschmuggler","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Whis·key·schmugg·ler","de-DE":"Whis·key·schmugg·ler"},"forms":[{"form":"Whiskeyschmuggler","tags":["Nominativ","Singular"]},{"form":"Whiskeyschmugglern","tags":["Dativ","Plural"]},{"form":"Whiskeyschmugglers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Person, die Whiskey schmuggelt"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Whiskey und Schmuggler"],"examples":[{"text":"„Sämtliche Autos der Whiskeyschmuggler in dem Film waren Originale.“","reference":"James Sallis: Driver. Liebeskind, München 2007, ISBN 978-3-935-89046-5, Seite 106 ."},{"text":"„Du weißt, wie dämlich er dastehen würde, wenn er einen Vierzehnjährigen einsperrt? Sogar wenn der ’nem Whiskeyschmuggler geholfen hat, vom Fallenstellen ohne Genehmigung ganz zu schweigen.“","reference":"Cormac McCarthy: Der Feldhüter. Rowohlt, Reinbek bei Hamburg 2016, ISBN 978-3-499-26798-7, Seite 181 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whiskeyschmuggler","id":"93a8a15659502c"},"0077-0068:1e823436e736fc":{"word":"Whiskeyglas","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Whis·key·glas","de-DE":"Whis·key·glas"},"forms":[{"form":"Whiskyglas","tags":["alternative"]},{"form":"Whiskeyglas","tags":["Nominativ","Singular"]},{"form":"Whiskeyglases","tags":["Genitiv","Singular"]},{"form":"Whiskeygläser","tags":["Nominativ","Plural"]},{"form":"Whiskeygläsern","tags":["Dativ","Plural"]}],"senses":[{"definition":"Glas, aus dem Whiskey getrunken wird"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Whiskey und Glas"],"examples":[{"text":"„Claude drehte sein Whiskeyglas zwischen den Handflächen und sagte, das Äußerste, was er erreichen könne, sei ein Schwarzflug mit einer C-130.“","reference":"Viet Thanh Nguyen: Der Sympathisant. Heyne, München 2018, ISBN 978-3-453-43960-3, Seite 16 ."},{"text":"„Wilson verzichtete darauf, den Besucher nach seinem Getränkewunsch zu fragen, und griff zielstrebig nach zwei Whiskeygläsern.“","reference":"Vince Flynn: Kill Shot. Festa, Leipzig 2016, ISBN 978-3-865-52457-7, Seite 77 ."},{"text":"„Er sinkt auf den Stuhl, greift nach dem leeren Whiskeyglas, späht hinein, als wäre es ein Teleskop, seufzt und bestellt einen neuen.“","reference":"Ian McGuire: Der Abstinent. dtv, München 2021, ISBN 978-3-423-28272-7, Seite 54 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whiskeyglas","id":"1e823436e736fc"},"0077-0068:cfe29cdfabba60":{"word":"Whodunit","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Whod·u·nit","de-DE":"Whod·u·nit"},"forms":[{"form":"Whodunit","tags":["Nominativ","Singular"]},{"form":"Whodunits","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Detektivgeschichte/Kriminalfall, bei dem die Identifizierung des Täters im Mittelpunkt steht"}],"synonyms":[],"origins":[],"examples":[{"text":"„In der Powder Mill Road bekam nun James einen harten Fall der Extraklasse, einen knallharten Whodunit.“","reference":"David Simon: Homicide. Ein Jahr auf mörderischen Straßen. Antje Kunstmann, München 2011, ISBN 978-3-888-97723-7, Seite 246 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whodunit","id":"cfe29cdfabba60"},"0077-0068:96fbd0bc011025":{"word":"Whiskey Soda","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Whis·key Soda","de-DE":"Whis·key Soda"},"forms":[{"form":"Whiskey Soda","tags":["Nominativ","Singular"]},{"form":"Whiskey Sodas","tags":["Nominativ","Plural"]}],"senses":[{"definition":"aus mit Sodawasser aufgeschüttetem Whiskey und Eis bestehender Cocktail"}],"synonyms":[],"origins":[],"examples":[{"text":"„Dann stützte ich ihn auf dem Weg in sein Arbeitszimmer, wo er sich auf dem Diwan ausstreckte, und reichte ihm ein Glas Whiskey Soda; die Getränke hatte ich in dem lackierten Schränkchen gefunden.“","reference":"Robert E. Howard: Die Kreatur mit den Hufen. In: Volk der Finsternis. Festa, Leipzig 2009, ISBN 978-3-865-52062-3, Seite 216 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whiskey Soda","id":"96fbd0bc011025"},"0077-0068:462160ae8f1bdb":{"word":"Whiskeyfass","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Whis·key·fass","de-DE":"Whis·key·fass"},"forms":[{"form":"Whiskeyfass","tags":["Nominativ","Singular"]},{"form":"Whiskeyfasses","tags":["Genitiv","Singular"]},{"form":"Whiskeyfässer","tags":["Nominativ","Plural"]},{"form":"Whiskeyfässern","tags":["Dativ","Plural"]}],"senses":[{"definition":"Fass, in dem Whiskey eingelagert ist"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Whiskey und Fass"],"examples":[{"text":"„Dahinter angebunden stand das in der Nacht zuvor geleerte Whiskeyfass.“","reference":"Cormac McCarthy: Die Abendröte im Westen. Rowohlt, Reinbek bei Hamburg 2016, ISBN 978-3-499-27240-0, Seite 338 ."},{"text":"„Ein Whiskeyfass wurde mit Tomahawks bearbeitet.“","reference":"Philipp Meyer: Der erste Sohn. Knaus, München 2014, ISBN 978-3-8135-0479-8, Seite 52 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whiskeyfass","id":"462160ae8f1bdb"},"0077-0068:3befeda0809bab":{"word":"Whiskey Sour","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Whis·key Sour","de-DE":"Whis·key Sour"},"forms":[{"form":"Whisky Sour","tags":["alternative"]},{"form":"Whiskey Sour","tags":["Nominativ","Singular"]},{"form":"Whiskey Sours","tags":["Nominativ","Plural"]}],"senses":[{"definition":"aus Whiskey, Zitronensaft und Zucker zubereiteter Drink"}],"synonyms":[],"origins":[],"examples":[{"text":"„Es ist erst halb neun morgens, aber der Herr möchte einen Whiskey Sour.“","reference":"David Ignatius: Operation Beirut. Rowohlt, Reinbek bei Hamburg 2011, ISBN 978-3-499-24910-5, Seite 554 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whiskey Sour","id":"3befeda0809bab"},"0077-0068:52fece1c4deeb5":{"word":"White Trash","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"White Trash","de-DE":"White Trash"},"forms":[{"form":"White Trash","tags":["Nominativ","Singular"]}],"senses":[{"definition":"abwertende Bezeichnung für Mitglieder der weißen Unterschicht vor allem in den Appalachen, den Südstaaten und den ländlichen Teilen der Vereinigten Staaten"}],"synonyms":[],"origins":[],"examples":[{"text":"„Knapp einen Meter hinter der Tür stand ein glatzköpfiger Mann Mitte 30, nackter Oberkörper, Brust und Nacken mit Tätowierungen übersät und glänzend vor Schweiß. In der Linken hielt er eine glimmende Zigarette. White Trash, wie er im Buche steht.“","reference":"Mark Greaney: The Gray Man - Operation Back Blast. Festa, Leipzig 2021, ISBN 978-3-86552-966-4, Seite 50 ."},{"text":"„Vergiss White Trash, vergiss die Rednecks, die weißen Zombies - gut betuchte Weiße wollen Schwarze retten.“","reference":"Mukoma wa Ngugi: Nairobi Heat. Transit, Berlin 2014, ISBN 978-3-88747-299-3, Seite 164 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"White Trash","id":"52fece1c4deeb5"},"0077-0068:8703960d247f17":{"word":"whiskeygetränkt","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"whis·key·ge·tränkt","de-DE":"whis·key·ge·tränkt"},"forms":[{"form":"whiskeygetränkt","tags":["Positiv"]},{"form":"whiskeygetränkte","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"whiskeygetränktem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"whiskeygetränkten","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"whiskeygetränkter","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"whiskeygetränktes","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist whiskeygetränkt","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist whiskeygetränkt","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist whiskeygetränkt","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind whiskeygetränkt","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"mit Whiskey vollgesogen"}],"synonyms":[],"origins":[],"examples":[{"text":"„Er schnappte sich das hinter der Theke liegende Feuerzeug und zündete das whiskeygetränkte Aufwischtuch an; es ging sofort in Flammen auf.“","reference":"Mark Greaney: The Gray Man - Tödliche Jagd. Festa, Leipzig 2022, ISBN 978-3-98676-004-5, Seite 179 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"whiskeygetränkt","id":"8703960d247f17"},"0077-0068:82ce2bd61cb8a0":{"word":"Whiskeyfahne","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Whis·key·fah·ne","de-DE":"Whis·key·fah·ne"},"forms":[{"form":"Whiskeyfahne","tags":["Nominativ","Singular"]},{"form":"Whiskeyfahnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"nach Whiskey riechender Atemgeruch"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Whiskey und Fahne"],"examples":[{"text":"„Der Mann hatte eine leichte Whiskeyfahne.“","reference":"Cormac McCarthy: Draußen im Dunkel. Rowohlt, Reinbek bei Hamburg 2013, ISBN 978-3-498-04331-5, Seite 71 ."},{"text":"„Quinn trat ganz dicht an Lennon heran, eine Brise trug die saure Whiskeyfahne des Stadtrats herüber.“","reference":"Stuart Neville: Blutige Fehde. Aufbau, Berlin 2012, ISBN 978-3-352-00839-9, Seite 211 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whiskeyfahne","id":"82ce2bd61cb8a0"},"0077-0068:7bd136e09ef619":{"word":"Whiskeykaraffe","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Whis·key·ka·raf·fe","de-DE":"Whis·key·ka·raf·fe"},"forms":[{"form":"Whiskeykaraffe","tags":["Nominativ","Singular"]},{"form":"Whiskeykaraffen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Karaffe, in der Whiskey serviert wird"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Whiskey und Karaffe"],"examples":[{"text":"„Mit wackligem Gang ging Hartshorn zur Anrichte und nahm die Whiskeykaraffe.“","reference":"James Ellroy: Blutschatten. Ullstein, Berlin 2018, ISBN 978-3-548-29001-0, Seite 279 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whiskeykaraffe","id":"7bd136e09ef619"},"0077-0068:5b179b0c5bc3ad":{"word":"Whiskydunst","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Whis·ky·dunst","de-DE":"Whis·ky·dunst"},"forms":[{"form":"Whiskydunst","tags":["Nominativ","Singular"]},{"form":"Whiskydunsts","tags":["Genitiv","Singular"]},{"form":"Whiskydünste","tags":["Nominativ","Plural"]},{"form":"Whiskydünsten","tags":["Dativ","Plural"]}],"senses":[{"definition":"von Whiskey ausgehender Dunst"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Whisky und Dunst"],"examples":[{"text":"„Holmes konnte die Whiskydünste aus Huttons Becher riechen und war angewidert und neidisch zugleich.“","reference":"Ian Rankin: Das zweite Zeichen. Goldmann, München 2001, ISBN 978-3-442-44608-7, Seite 103 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whiskydunst","id":"5b179b0c5bc3ad"},"0077-0068:cd69e7bb8412cf":{"word":"Whiskeybrennen","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Whis·key·bren·nen","de-DE":"Whis·key·bren·nen"},"forms":[{"form":"Whiskybrennen","tags":["alternative"]},{"form":"Whiskeybrennen","tags":["Nominativ","Singular"]},{"form":"Whiskeybrennens","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Herstellung von Whiskey durch Destillation"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Whiskey und Brennen"],"examples":[{"text":"„Die Familie hatte schon Whiskey gebrannt, bevor das Whiskeybrennen ungesetzlich war, und ihre Familiengeschichte war mythisch und legendär, ihre Anfänge vor aller Schrift.“","reference":"Cormac McCarthy: Der Feldhüter. Rowohlt, Reinbek bei Hamburg 2016, ISBN 978-3-499-26798-7, Seite 109 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whiskeybrennen","id":"cd69e7bb8412cf"},"0077-0068:424f7a92551e7c":{"word":"Whiskeyaroma","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Whis·key·aro·ma","de-DE":"Whis·key·aro·ma"},"forms":[{"form":"Whiskyaroma","tags":["alternative"]},{"form":"Whiskeyaroma","tags":["Nominativ","Singular"]},{"form":"Whiskeyaromas","tags":["Genitiv","Singular"]},{"form":"Whiskeyaromen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Geschmack und/oder Geruch nach Whiskey"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Whiskey und Aroma"],"examples":[{"text":"„Jeffrey ließ die goldene Flüssigkeit im Glas kreisen, sodass das Whiskeyaroma durch den Raum schwebte, während er den Bildschirm betrachtete.“","reference":"Chang Kuo-Li: Die Kugeln des Bösen. Droemer, München 2024, ISBN 978-3-426-28414-8, Seite 197 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whiskeyaroma","id":"424f7a92551e7c"},"0077-0068:06eb277216ca05":{"word":"Whiskeyverkäufer","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Whis·key·ver·käu·fer","de-DE":"Whis·key·ver·käu·fer"},"forms":[{"form":"Whiskyverkäufer","tags":["alternative"]},{"form":"Whiskeyverkäufer","tags":["Nominativ","Singular"]},{"form":"Whiskeyverkäufern","tags":["Dativ","Plural"]},{"form":"Whiskeyverkäufers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Person, die Whiskey verkauft"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Whiskey und Verkäufer"],"examples":[{"text":"„Es war ein ausgedehntes Unternehmen von Whiskeyverkäufern, Händlern, Dieben, Spielern, Huren, Marketendern und Schaustellern geworden.“","reference":"James Carlos Blake: Das Böse im Blut. Liebeskind, München 2013, ISBN 978-3-95438-016-9, Seite 151 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whiskeyverkäufer","id":"06eb277216ca05"},"0077-0068:53ef7c8fad6df4":{"word":"Whlg.","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"Whl·g.","de-DE":"Whl·g."},"forms":[{"form":"Wdh.","tags":["alternative"]},{"form":"Wdhg.","tags":["alternative"]},{"form":"Wdhl.","tags":["alternative"]},{"form":"Wdlg.","tags":["alternative"]},{"form":"Wdhlg.","tags":["alternative"]}],"senses":[{"definition":"Abkürzung von Wiederholung"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Whlg.","id":"53ef7c8fad6df4"},"0077-0068:6a4ca462312478":{"word":"White River","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"White Ri·ver","de-DE":"White Ri·ver"},"forms":[{"form":"White Rivers","tags":["Genitiv","Singular"]},{"form":"des White River","tags":["Genitiv","Singular"]},{"form":"des White Rivers","tags":["Genitiv","Singular"]},{"form":"(das) White River","tags":["Nominativ","Singular"]},{"form":"(dem) White River","tags":["Dativ","Singular"]}],"senses":[{"definition":"Ort in der südafrikanischen Provinz Mpumalanga"}],"synonyms":[],"origins":[],"examples":[{"text":"„Durch White River, der Unterschied zum Kap war deutlich - hier strahlten die Farben der Natur: das Blattwerk der endlosen Bäume, das Blutrot fast jeder Blume, das tiefe Mahagonibraun der Menschen, die Stände am Straßenrand betrieben.“","reference":"Deon Meyer: Weißer Schatten. Aufbau, Berlin 2008, ISBN 978-3-352-00759-0, Seite 46 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"White River","id":"6a4ca462312478"},"0077-0068:b10786726f0eb5":{"word":"White-Box-Test","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"White-Box-Test","de-DE":"White-Box-Test"},"forms":[{"form":"White-Box-Test","tags":["Nominativ","Singular"]},{"form":"White-Box-Tests","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Softwaretest mit Kenntnissen über die innere Funktionsweise des zu testenden Systems"}],"synonyms":[],"origins":["aus dem englischen Begriff white-box test"],"examples":[{"text":"„Ein Beispiel für einen White-Box-Test ist ablaufbezogenes Testen (Kontrollflussorientierte Testverfahren), bei welchem der Ablaufgraph im Vordergrund steht.“","reference":"Wikipedia-Artikel „White-Box-Test“ (Stabilversion)"},{"text":"„Testfälle aus einer informalen Spezifikation abzuleiten, ist vergleichsweise aufwändig und je nach Präzisionsgrad der Spezifikation u. U. nicht möglich. Oft ist daher ein vollständiger Black-Box-Test ebenso wenig wirtschaftlich wie ein vollständiger White-Box-Test.“","reference":"Wikipedia-Artikel „Black-Box-Test“ (Stabilversion)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"White-Box-Test","id":"b10786726f0eb5"}};
